/* Bilingual simulation study. Published results remain in the frozen data export. */
window.reportChapter = function (chapter, language) {
  const t = (zh, en) => language === 'en' ? en : zh;
  const p = (zh, en) => `<p>${t(zh, en)}</p>`;
  const heading = (number, zh, en, id) => `<h2${id ? ` id="${id}" tabindex="-1"` : ''}><span>${number}</span>${t(zh, en)}</h2>`;
  const escapeMath = tex => tex.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
  const inline = tex => `\\(${escapeMath(tex)}\\)`;
  const equation = (tex, label = '') => `<div class="equation"><div>\\[${escapeMath(tex)}\\]</div>${label ? `<span>${label}</span>` : ''}</div>`;
  const note = (title, zh, en) => `<aside class="note"><strong>${title}</strong>${p(zh, en)}</aside>`;
  const table = (headers, rows, caption = '') => `<div class="table-wrap" tabindex="0" role="region" aria-label="${caption || headers[0]}"><table>${caption ? `<caption>${caption}</caption>` : ''}<thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map((cell, i) => `<${i ? 'td' : 'th scope="row"'}>${cell}</${i ? 'td' : 'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const pending = (title, zh, en) => `<div class="pending-box"><span class="status-label">${t('研究說明', 'Study note')}</span><h3>${title}</h3>${p(zh, en)}</div>`;
  const reference = (url, title) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`;
  const ready = () => Boolean(window.MechanismResults?.ready());
  const views = {
    overview: () => `
      <div class="chapter-heading"><span class="chapter-number">01 / OVERVIEW</span><h1>Static and Dynamic Graph Construction for GNNs</h1><p class="subtitle">${t('圖資訊、鄰居加權與拓樸變動，何時能改善預測？','When do graph information, neighbor weighting, and topology changes improve prediction?')}</p></div>
      <div class="abstract"><h2>${t('研究摘要','Abstract')}</h2>${p('本專題以可控制的合成資料，比較 MLP、Static GCN、Static GAT、Dynamic GCN 與 Dynamic GAT。研究依序改變生成機制，在同一資料與時間切分上比較五模型，再用配對差值、反應曲線與診斷相圖分析它們的相對優勢。','This study compares MLP, Static GCN, Static GAT, Dynamic GCN, and Dynamic GAT on controlled synthetic data. Models share datasets and chronological splits. Paired gaps, response curves, and diagnostic maps show how their relative advantages respond to changes in the data-generating mechanism.')}</div>
      ${heading('1.1','三個研究問題','Three research questions')}
      ${table([t('比較','Comparison'),t('要解釋的問題','Question to explain')],[
        [inline(String.raw`\mathrm{GNN}-\mathrm{MLP}`),t('圖是否提供自身特徵之外的預測資訊？','Does the graph add predictive information beyond local features?')],
        [inline(String.raw`\mathrm{GAT}-\mathrm{GCN}`),t('鄰居重要性不同時，學習加權是否有益？','Does learned weighting help when neighbors differ in relevance?')],
        [inline(String.raw`\text{Dynamic}-\text{Static}`),t('拓樸變動是有用訊號，還是觀測雜訊？','Does changing topology contain useful signal or observation noise?')]
      ])}
      ${p('主要任務是以當期特徵預測下一期連續目標；圖平滑度另做同時點去噪，分類作為穩健性檢查。這些任務分開解讀，並以跨資料種子的配對差值為證據。','The primary task predicts a next-step continuous target from current features. Smoothness uses a separate same-time denoising task, while classification checks robustness. These tasks are interpreted separately using paired comparisons across dataset seeds.')}
      ${heading('1.2','研究流程與閱讀指南','Workflow and reading guide')}
      <ol class="workflow">${[
        [t('先理解模型','Understand the models'),t('「圖與模型」定義圖與聚合；「互動算例」用同一組節點逐步比較計算。','Graphs & Models defines graphs and aggregation. Interactive Example compares computations on one shared set of nodes.'),'models',t('圖與模型','Graphs & Models'),'walkthrough',t('互動算例','Interactive Example')],
        [t('再看實驗如何建立','Examine how experiments are built'),t('「資料生成」說明機制；「實驗與評估」定義診斷、配對比較與公平評估。','Data Generation specifies mechanisms. Experiments & Evaluation defines diagnostics, paired comparisons, and fair evaluation.'),'generation',t('資料生成','Data Generation'),'design',t('實驗與評估','Experiments & Evaluation')],
        [t('最後評估證據','Assess the evidence'),t('「模擬結果」呈現曲線與相圖；「討論與結論」整理穩健性、支持程度與適用範圍。','Simulation Results presents curves and maps. Discussion & Conclusions examines robustness, support for the hypotheses, and scope.'),'results',t('模擬結果','Simulation Results'),'discussion',t('討論與結論','Discussion & Conclusions')]
      ].map(([title,text,first,firstLabel,second,secondLabel],i)=>`<li><span>${i+1}</span><div><h3>${title}</h3><p>${text}</p><p><a href="#${first}">${firstLabel}</a> · <a href="#${second}">${secondLabel}</a></p></div></li>`).join('')}</ol>
      ${heading('1.3','研究產出與邊界','Outputs and scope')}
      ${p('完整套件已完成 7,240 次模型評估，另有獨立 Stage A 機制檢查 150 次；這是模型評估數，不是獨立資料集數。研究成果為指定生成器與調參預算下的模型行為證據，尚不能視為普遍適用的自動選模規則。','The complete suite contains 7,240 model evaluations, plus 150 separately executed Stage A evaluations; these are evaluation counts, not independent datasets. Findings characterize behavior under the tested generators and tuning budgets, rather than a universal automatic selection rule.')}
      <p class="caption">${ready()?t('封存結果已接入，可直接前往「模擬結果」。','Archived results are loaded; continue to Simulation Results.'):t('模擬已完成；網頁結果資料尚未載入。','Simulation is complete; website results have not loaded yet.')}</p>
    `,
    models: () => `
      <div class="chapter-heading"><span class="chapter-number">02 / GRAPHS & MODELS</span><h1>${t('圖與五種模型如何運作','How graphs and the five models work')}</h1><p class="subtitle">${t('從圖與節點特徵出發，說明訊息傳遞、靜態／動態差異，以及研究實際採用的預測架構。','Define graphs and node features, inspect message passing, and connect static/dynamic choices to the implemented prediction architecture.')}</p></div>
      ${heading('2.1', 'Graph、特徵與鄰接矩陣', 'Graphs, features, and adjacency matrices')}
      ${p(`圖 ${inline('G=(V,E)')} 由節點集合 ${inline('V')} 與邊集合 ${inline('E')} 組成。本研究的節點是合成資料中的預測單位；邊指定哪些鄰居可以傳遞訊息。生成機制中的真實圖決定目標如何形成，觀測圖則是模型的輸入，兩者可以因觀測雜訊而不同。`,`A graph ${inline('G=(V,E)')} contains a node set ${inline('V')} and an edge set ${inline('E')}. Nodes are prediction units in synthetic data, and edges specify allowed message sources. The true generator graph determines how targets form; the observed graph is an input to the model and can differ because of observation noise.`)}
      <details class="technical-details"><summary>${t('術語對照：節點、邊、特徵與表示','Terminology: nodes, edges, features, and embeddings')}</summary>
      ${table([t('名詞／符號','Term / symbol'),t('定義','Definition'),t('本研究中的例子','Example in this study')],[
        ['Node · '+inline(String.raw`i\in V`),t('一個具有特徵與目標的合成單位。','A synthetic unit with features and a target.'),t(`同一時間切片中的第 ${inline('i')} 個節點。`,`Node ${inline('i')} in a snapshot.`)],
        ['Edge · '+inline(String.raw`(j,i)\in E`),t(`允許 ${inline('j')} 的訊息進入 ${inline('i')} 的關係。`,`A relation allowing a message from ${inline('j')} to enter ${inline('i')}.`),t('規則圖中的鄰居關係，或重連後的新鄰居。','A regular-graph neighbor or a new neighbor after rewiring.')],
        ['Feature · '+inline(String.raw`x_{i,t}\in\mathbb R^8`),t('節點當期的八維數值描述；模型不讀取歷史目標。','Eight current node features; models do not receive response history.'),t('各四維的自身訊號與鄰居內容特徵區塊。','Four self-signal features and four neighbor-content features.')],
        ['Adjacency · '+inline(String.raw`A_t\in\{0,1\}^{N\times N}`),t(`${inline('(A_t)_{ij}=1')} 表示允許 ${inline(String.raw`j\to i`)} 傳訊；主實驗使用無向圖。`,`${inline('(A_t)_{ij}=1')} allows a message ${inline(String.raw`j\to i`)}; primary experiments use undirected graphs.`),t('圖本身為二元連線；GCN 正規化係數與 GAT 注意力則為實數權重。','Connectivity is binary; GCN normalization and GAT attention provide real-valued aggregation weights.')],
        ['Neighborhood · '+inline(String.raw`\widetilde{\mathcal N}_t(i)`),t('鄰居與節點自身組成的訊息來源集合。','Neighbors plus the node itself form the message-source set.'),t(`若 ${inline('i')} 連到 ${inline('B,C')}，來源為 ${inline(String.raw`\{i,B,C\}`)}。`,`If ${inline('i')} connects to ${inline('B,C')}, sources are ${inline(String.raw`\{i,B,C\}`)}.`)],
        ['Embedding · '+inline('h_i'),t('非線性編碼器學到的節點表示。','A representation learned by the nonlinear node encoder.'),t('供自身分支與鄰居聚合使用的向量。','A vector used by both the local branch and neighbor aggregation.')]
      ])}
      </details>
      ${heading('2.2', '靜態圖、動態圖與注意力的差別', 'Static graphs, dynamic graphs, and attention')}
      ${equation(String.raw`\text{Static: }A_t^{\mathrm{model}}=A^{\mathrm{Static}}\quad\forall t,\qquad \text{Dynamic: }A_t^{\mathrm{model}}=A_t^{\mathrm{obs}}`,'(3)')}
      ${p('Static 模型共用只由訓練期觀測圖建立的固定圖；Dynamic 模型使用各時間切片的觀測圖。真實拓樸漂移實驗改變生成目標的鄰居，圖雜訊實驗則保持生成圖固定、只擾動模型觀測到的邊。結構會變動，並不保證變動有預測價值。', 'Static models share a fixed graph constructed from training-period observations. Dynamic models use each snapshot’s observed graph. True topology drift changes the neighbors generating the target; graph-noise experiments hold that generator fixed while perturbing observed edges. Structural change alone need not have predictive value.')}
      ${note(t('兩個分開控制的因素','Two separate factors'),'Static／Dynamic 控制鄰居集合是否更新；GCN／GAT 控制如何加權。因此 Static GAT 的注意力仍可隨輸入改變，Dynamic GCN 的係數則由當期圖的度數決定。','Static/Dynamic controls whether neighborhoods update; GCN/GAT controls weighting. Static GAT can vary attention with its inputs, while Dynamic GCN uses degree-based coefficients for the current graph.')}
      ${heading('2.3', 'MLP、GCN 與 GAT 的計算', 'How MLP, GCN, and GAT compute')}
      <h3>MLP · ${t('多層感知器','Multilayer perceptron')}</h3>
      ${p('MLP 重複線性變換與非線性激活來學習節點自身特徵的函數。在本研究，五模型皆先使用相同形式的兩層節點編碼器；MLP 的訊息分支仍只來自自身，因此不會額外取得其他節點的特徵。', 'An MLP stacks affine transformations and nonlinear activations to learn functions of local features. All five models use the same form of two-layer node encoder. MLP keeps its message branch local and therefore receives no additional node features.')}
      ${equation(String.raw`h_i^{(\ell+1)}=\operatorname{ReLU}\!\left(W^{(\ell)}h_i^{(\ell)}+b^{(\ell)}\right),\qquad h_i=\operatorname{Encoder}_\theta(x_i)`,'(4)')}
      <h3>GCN · ${t('圖卷積網路','Graph convolutional network')}</h3>
      ${p(`GCN 依鄰接矩陣聚合鄰居的 value 向量。加入自迴路後 ${inline(String.raw`\widehat A=A+I`)}，${inline(String.raw`\widehat D`)} 的對角元素是其列和。下式是研究使用的無向圖對稱正規化；只有度數相同的規則圖，係數才退化成一致的鄰域平均。`,`GCN aggregates neighbor value vectors according to adjacency. Add self-loops with ${inline(String.raw`\widehat A=A+I`)} and let ${inline(String.raw`\widehat D`)} contain its row sums. The implementation uses symmetric normalization for undirected graphs. Uniform neighborhood averaging follows only when degrees are equal.`)}
      ${equation(String.raw`v_j=W_vh_j+b_v,\qquad M=\widehat D^{-1/2}\widehat A\widehat D^{-1/2}V,\qquad m_i=\sum_{j\in\widetilde{\mathcal N}(i)}\frac{v_j}{\sqrt{\widehat d_i\widehat d_j}}`,'(5)')}
      <p class="reference-line">${reference('https://arxiv.org/abs/1609.02907','Kipf & Welling (2017), Semi-Supervised Classification with Graph Convolutional Networks')}</p>
      <h3>GAT · ${t('圖注意力網路','Graph attention network')}</h3>
      ${p(`GAT 根據編碼後的目標與來源特徵計算分數 ${inline('e_{ij}')}，再以 softmax 形成總和為 ${inline('1')} 的鄰居權重 ${inline(String.raw`\alpha_{ij}`)}。下式對應本研究 vanilla GAT 的單頭加法注意力：計分使用編碼表示，加權內容使用 value 投影。權重是模型參數與輸入共同產生的計算量。`,`GAT computes scores ${inline('e_{ij}')} from encoded target and source features, then normalizes them into weights ${inline(String.raw`\alpha_{ij}`)} summing to ${inline('1')}. These equations match the implemented single-head additive vanilla GAT: scores use encoded features and weighted content uses a value projection. Attention is a model quantity determined by parameters and inputs.`)}
      ${equation(String.raw`e_{ij}=\operatorname{LeakyReLU}\!\left(a_q^\top h_i+a_s^\top h_j\right),\qquad\alpha_{ij}=\frac{\exp(e_{ij})}{\sum_{k\in\widetilde{\mathcal N}(i)}\exp(e_{ik})}`,'(6)')}
      ${equation(String.raw`m_i=\sum_{j\in\widetilde{\mathcal N}(i)}\alpha_{ij}v_j,\qquad v_j=W_vh_j+b_v`,'(7)')}
      <p class="reference-line">${reference('https://arxiv.org/abs/1710.10903','Veličković et al. (2018), Graph Attention Networks')}</p>
      ${p('同一時間切片內，GCN 與 GAT 都只做一次鄰居聚合。Static／Dynamic 決定採用哪個鄰居集合；GCN／GAT 決定如何對允許來源加權。穩健性實驗另外加入 GATv2，檢查需要依目標節點改變來源排序的機制；它不改變主要五模型的比較範圍。', 'Within a snapshot, GCN and GAT both use one neighborhood aggregation. Static/Dynamic selects the neighbor set; GCN/GAT selects how allowed sources are weighted. Robustness experiments add GATv2 for mechanisms requiring target-dependent source rankings, without changing the main five-model comparison.')}
      ${heading('2.4', '正式模型如何輸出回歸與分類？', 'How the implemented model predicts regression and classification')}
      ${p('正式模型保留自身表示，與訊息分支串接後交給共同形式的預測頭；因此使用圖不會迫使模型捨棄自身訊號。MLP 的訊息分支只是自身的 value 向量，圖模型則使用前述聚合訊息。輸出頭是包含 ReLU 的兩層 MLP，產生一個實數。', 'The implemented model retains local representations and concatenates them with the message branch before a shared form of prediction head. Graph aggregation therefore does not discard the local signal. MLP uses its own value vector as the message; graph models use the aggregation above. A two-layer ReLU MLP head produces one real-valued output.')}
      ${equation(String.raw`\widehat y_i=\operatorname{Head}_\theta([h_i\,\Vert\,m_i]),\qquad m_i^{\mathrm{MLP}}=v_i`,'(8a)')}
      ${p(`回歸以訓練期均值與尺度標準化目標，最小化均方誤差；測試預測會轉回原尺度。主要比較分數為 ${inline('R^2')}，數值越高越好。`,`Regression standardizes targets using training-period moments and minimizes mean squared error; predictions are transformed back to the original scale. The primary comparison score is ${inline('R^2')}, with larger values preferred.`)}
      ${equation(String.raw`\mathcal L_{\mathrm{MSE}}=\frac1{|\mathcal I_{\mathrm{train}}|}\sum_{(i,t)\in\mathcal I_{\mathrm{train}}}(\widehat y_{i,t}-y_{i,t})^2,\qquad R^2=1-\frac{\sum(\widehat Y-Y)^2}{\sum(Y-\overline Y)^2}`,'(8b)')}
      <details class="technical-details"><summary>${t('分類穩健性：logit、sigmoid 與訓練損失','Classification robustness: logits, sigmoid, and training loss')}</summary>
      ${p('分類穩健性實驗沿用相同模型，以實數輸出作為 logit，用數值穩定的 binary cross-entropy 訓練；sigmoid 僅將輸出轉成機率。訓練損失、驗證選擇與最後報告的排序分數是不同量，分類主要報告 average precision。', 'Classification robustness uses the same model output as a logit and trains with numerically stable binary cross-entropy. A sigmoid converts logits to probabilities. Training loss, validation selection, and the reported ranking score are distinct quantities; average precision is the primary classification score.')}
      ${equation(String.raw`\widehat p_i=\operatorname{sigmoid}(\widehat y_i),\qquad\mathcal L_{\mathrm{BCE}}=-\frac1{|\mathcal I_{\mathrm{train}}|}\sum_{q\in\mathcal I_{\mathrm{train}}}\left[y_q\log\widehat p_q+(1-y_q)\log(1-\widehat p_q)\right]`,'(8c)')}
      </details>
    `,
    walkthrough: () => `
      <div class="chapter-heading"><span class="chapter-number">03 / INTERACTIVE EXAMPLE</span><h1>${t('互動算例：看見一次訊息更新','Interactive example: inspect one message update')}</h1><p class="subtitle">${t('保持同一組節點與特徵，逐步比較資訊來源、權重、加總與非線性輸出。','Hold nodes and features fixed, then compare information sources, weights, sums, and nonlinear output.')}</p></div>
      ${heading('3.1','算例設定','Example settings')}
      ${p(`使用四個節點 ${inline('i,B,C,D')}，初始純量特徵為 ${inline('2,1,4,3')}。固定圖讓 ${inline('i')} 與 ${inline('B,C')} 相連；動態圖在 ${inline('t_1')} 把 ${inline('C')} 換成 ${inline('D')}。選擇模型、調整特徵，再逐步查看權重、加總與輸出。`,`Use four nodes ${inline('i,B,C,D')} with initial scalar features ${inline('2,1,4,3')}. The static graph connects ${inline('i')} to ${inline('B,C')}; at ${inline('t_1')} the dynamic graph replaces ${inline('C')} with ${inline('D')}. Choose a model, change a feature, and inspect weighting, aggregation, and output.`)}
      ${note(t('算例的設定與限制','Teaching-example settings'),`這是可重算的純量例子，不是訓練結果，也省略正式模型的編碼器與預測頭。令 ${inline('W=1')}、${inline('b=0')}，最後套用 ${inline(String.raw`\operatorname{ReLU}`)}；GAT 取 ${inline('a=(0,1)')}，LeakyReLU 負斜率為 ${inline('0.2')}。GCN 使用含自迴路的無向星狀圖。最後數值只表示一次訊息更新，不是研究成績或分類機率。`,`This reproducible scalar example is untrained and omits the full encoder and prediction head. Set ${inline('W=1')} and ${inline('b=0')}, followed by ${inline(String.raw`\operatorname{ReLU}`)}; GAT uses ${inline('a=(0,1)')} with LeakyReLU slope ${inline('0.2')}. GCN uses an undirected star graph with self-loops. Its output illustrates one message update, not benchmark performance or a class probability.`)}
      ${heading('3.2','逐步操作與計算','Step through the calculation')}
      <div class="lesson"><div class="lesson-toolbar"><label for="lesson-model">${t('模型','Model')}<select id="lesson-model">${['MLP','Static GCN','Static GAT','Dynamic GCN','Dynamic GAT'].map(m=>`<option>${m}</option>`).join('')}</select></label><div><span class="control-label">${t('時間切片','Time slice')}</span><div class="segmented" role="group" aria-label="${t('時間切片','Time slice')}"><button data-lesson-time="0">${inline('t_0')}</button><button data-lesson-time="1">${inline('t_1')}</button></div></div><button id="lesson-reset" class="secondary-button">${t('重設算例','Reset example')}</button></div><div class="lesson-grid"><div class="lesson-diagram"><svg id="lesson-graph" viewBox="0 0 430 310" role="img" aria-label="${t('目標與三個候選鄰居的圖','Target and three candidate neighbors')}"></svg><p id="lesson-graph-caption" class="caption"></p><div class="feature-control"><label for="feature-node">${t('修改節點','Edit node')}<select id="feature-node"><option value="0">i</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label><label for="feature-value">${t('特徵值','Feature value')} <output id="feature-output"></output><input id="feature-value" type="range" min="-3" max="6" step="0.5" value="2"></label></div></div><div class="lesson-calculation"><div class="step-controls"><button id="lesson-previous" class="secondary-button">${t('上一步','Previous')}</button><span id="lesson-step-count"></span><button id="lesson-next" class="primary-button">${t('下一步','Next')}</button></div><h3 id="lesson-step-title"></h3><p id="lesson-step-description"></p><div id="lesson-weights"></div><div id="lesson-result" role="status" aria-live="polite"></div></div></div></div>
      ${heading('3.3','如何解讀這個算例？','How should the example be read?')}
      <ol class="numbered-prose"><li>${t('先固定特徵，比較 MLP 與圖模型各自讀到哪些來源；未連接的節點不會直接參與一次聚合。','Keep features fixed and compare the sources available to MLP and graph models. Disconnected nodes do not directly enter a single aggregation.')}</li><li>${t(`固定圖後修改 ${inline('C')} 的特徵，觀察 GAT 權重是否改變；GCN 的係數仍由圖的度數決定。`,`Hold the graph fixed and change ${inline('C')}’s feature. Inspect how GAT weights respond while GCN coefficients remain determined by graph degrees.`)}</li><li>${t(`切換 ${inline('t_0')} 與 ${inline('t_1')}，檢查 Dynamic 的鄰居替換與 Static 的固定集合。這展示計算機制；模型是否因此有更好的泛化表現，須由「模擬結果」判斷。`,`Switch between ${inline('t_0')} and ${inline('t_1')} to compare updated Dynamic neighborhoods with the fixed Static set. This illustrates computation; the Simulation Results chapter tests whether it improves generalization.`)}</li></ol>
    `,
    generation: () => window.generationChapter(t, p, heading, equation, note, table, pending),
    design: () => window.designChapter(t, p, heading, equation, note, table, pending),
    results: () => window.resultsChapter(t, p, heading, equation, note, table, pending),
    discussion: () => window.discussionChapter(t, p, heading, equation, note, table, pending)
  };
  return (views[chapter] || views.overview)();
};
